import React, { ComponentType, useEffect } from "react"
import { RenderTarget } from "framer"
import { animate, motion, motionValue, useTransform } from "framer-motion"

const PAGE_COUNT = 9
const RAIL_WIDTH = 26
const DESIGN_WIDTH = 1200
const clamp = (value: number, min: number, max: number) =>
    Math.min(max, Math.max(min, value))

const journeyProgress = motionValue(0)
let journeyTarget = 0
let journeyAnimation: ReturnType| null = null
let journeyUsers = 0

function attachJourneyWheel() {
    journeyUsers += 1
    if (journeyUsers > 1) return () => detachJourneyWheel()

const onWheel = (event: WheelEvent) => {
    if (Math.abs(event.deltaY) < Math.abs(event.deltaX)) return
    event.preventDefault()
    const scale = Math.max(window.innerHeight * 0.7, 420)
    journeyTarget = clamp(
        journeyTarget + event.deltaY / scale,
        0,
        PAGE_COUNT - 1
    )
    journeyAnimation?.stop()
    journeyAnimation = animate(journeyProgress, journeyTarget, {
        duration: 0.85,
        ease: [0.22, 1, 0.36, 1],
    })
}

window.addEventListener("wheel", onWheel, { passive: false })
return () => {
    window.removeEventListener("wheel", onWheel)
    detachJourneyWheel()
}

}

function detachJourneyWheel() {
    journeyUsers = Math.max(0, journeyUsers - 1)
}

export function withHorizontalJourneyRoot(
    Component: ComponentType): ComponentType{
    return function HorizontalJourneyRoot(props: any) {
        const isCanvas = RenderTarget.current() === RenderTarget.canvas

useEffect(() => {
        if (isCanvas) return

        const htmlOverflow = document.documentElement.style.overflow
        const bodyOverflow = document.body.style.overflow
        document.documentElement.style.overflow = "hidden"
        document.body.style.overflow = "hidden"

        journeyTarget = 0
        journeyProgress.set(0)
        const detachWheel = attachJourneyWheel()

        return () => {
            detachWheel()
            journeyAnimation?.stop()
            document.documentElement.style.overflow = htmlOverflow
            document.body.style.overflow = bodyOverflow
        }
    }, [isCanvas])

    return (
        <Component
            {...props}
            style={{
                ...props.style,
                position: "relative",
                width: isCanvas ? DESIGN_WIDTH : "100vw",
                maxWidth: "none",
                margin: 0,
                transform: "none",
                minHeight: isCanvas ? 2400 : "100vh",
                height: isCanvas ? 2400 : "100vh",
                overflow: "visible",
            }}
        />
    )
}

}

function makeHorizontalPage(
    Component: ComponentType,
    index: number
): ComponentType{
    return function HorizontalPage(props: any) {
        const isCanvas = RenderTarget.current() === RenderTarget.canvas
        const x = useTransform(journeyProgress, (value) => {
            if (typeof window === "undefined") return index * DESIGN_WIDTH
            const journeyWidth = Math.max(window.innerWidth - RAIL_WIDTH, 1)
            return (index - value) * journeyWidth
        })

if (isCanvas) {
        return (
            <Component
                {...props}
                style={{
                    ...props.style,
                    position: "relative",
                    width: "100%",
                    height: 800,
                    overflow: "hidden",
                }}
            />
        )
    }

    return (
        <motion.div
            style={{
                position: "fixed",
                left: `calc(${RAIL_WIDTH}px - (100vw - ${DESIGN_WIDTH}px) / 2)`,
                top: 0,
                width: `calc(100vw - ${RAIL_WIDTH}px)`,
                height: "100vh",
                x,
                overflow: "hidden",
                willChange: "transform",
                zIndex: 1,
            }}
        >
            <Component
                {...props}
                style={{
                    ...props.style,
                    position: "absolute",
                    inset: 0,
                    width: "100%",
                    height: "100%",
                    maxWidth: "none",
                    margin: 0,
                    transform: "none",
                    overflow: "hidden",
                }}
            />
        </motion.div>
    )
}

}

